import { useState } from 'react'
import {
  Shield,
  UserCog,
  Plus,
  Pencil,
  Trash2,
  CheckCircle2,
  AlertCircle,
  RefreshCw,
  Loader2,
  User,
  CloudUpload,
} from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Checkbox } from '@/components/ui/checkbox'
import { useToast } from '@/hooks/use-toast'
import useUsersStore, { SystemUser, usersStore } from '@/stores/users'
import useMainStore, { mainStore } from '@/stores/main'
import { Role } from '@/lib/permissions'

const availableRoles: Role[] = [
  'Admin',
  'Diretor',
  'Gerente',
  'Gestor de Contrato',
  'Vistoriador',
  'Jurídico',
  'Financeiro',
  'Corretor',
]

export default function PermissionsSettings() {
  const { users } = useUsersStore()
  const store = useMainStore()
  const { primaryDomain, clientId, tenantId } = store.sharepoint
  const { settings } = store
  const { toast } = useToast()

  const [dialogOpen, setDialogOpen] = useState(false)
  const [editId, setEditId] = useState<string | null>(null)
  const [isSyncing, setIsSyncing] = useState(false)

  const [formData, setFormData] = useState({ name: '', role: 'Vistoriador' as Role })
  const [localEmailPart, setLocalEmailPart] = useState('')

  const handleRoleChange = (userId: string, newRole: Role) => {
    usersStore.updateUserRole(userId, newRole)
    toast({
      title: 'Permissões Atualizadas',
      description: `O perfil de acesso foi alterado para ${newRole}.`,
    })
  }

  const handleOpenNew = () => {
    setEditId(null)
    setLocalEmailPart('')
    setFormData({ name: '', role: 'Vistoriador' })
    setDialogOpen(true)
  }

  const handleOpenEdit = (user: SystemUser) => {
    setEditId(user.id)
    const [local] = user.email.split('@')
    setLocalEmailPart(local)
    setFormData({ name: user.name, role: user.role })
    setDialogOpen(true)
  }

  const handleRemove = (id: string) => {
    usersStore.removeUser(id)
    toast({ title: 'Usuário Removido', description: 'Acesso revogado com sucesso.' })
  }

  const handleSave = () => {
    if (!formData.name || !localEmailPart || !primaryDomain) {
      toast({ variant: 'destructive', title: 'Erro', description: 'Preencha todos os campos.' })
      return
    }

    const fullEmail = `${localEmailPart}@${primaryDomain}`

    if (editId) {
      usersStore.updateUser(editId, { ...formData, email: fullEmail })
      toast({ title: 'Usuário Atualizado', description: 'Dados salvos com sucesso.' })
    } else {
      usersStore.addUser({ ...formData, email: fullEmail })
      toast({ title: 'Usuário Adicionado', description: 'Novo acesso concedido à organização.' })
    }
    setDialogOpen(false)
  }

  const toggleSpIntegrationRole = (role: Role, checked: boolean) => {
    const currentRoles = settings.spIntegrationRoles || []
    let newRoles = [...currentRoles]

    if (checked) {
      if (!newRoles.includes(role)) newRoles.push(role)
    } else {
      newRoles = newRoles.filter((r) => r !== role)
    }

    mainStore.updateSettings({ spIntegrationRoles: newRoles })
    toast({
      title: 'Permissões de Integração Atualizadas',
      description: `O acesso do perfil ${role} ao SharePoint foi modificado.`,
    })
  }

  const handleSyncM365 = async () => {
    if (!primaryDomain) return
    setIsSyncing(true)

    const token = sessionStorage.getItem('m365_token')

    if (token && clientId && tenantId) {
      try {
        const response = await fetch(
          'https://graph.microsoft.com/v1.0/users?$select=id,displayName,mail,userPrincipalName',
          {
            headers: { Authorization: `Bearer ${token}` },
          },
        )

        if (!response.ok) {
          const err = await response.json().catch(() => null)
          throw new Error(
            err?.error?.message ||
              'Falha ao buscar usuários da Graph API. Verifique as permissões de leitura (User.ReadBasic.All).',
          )
        }

        const data = await response.json()
        const graphUsers = data.value || []

        const validUsers = graphUsers
          .filter((u: any) => {
            const email = (u.mail || u.userPrincipalName || '').toLowerCase()
            return email.endsWith(`@${primaryDomain.toLowerCase()}`)
          })
          .map((u: any) => ({
            id: u.id,
            name: u.displayName || 'Usuário M365',
            email: (u.mail || u.userPrincipalName).toLowerCase(),
            role: 'Vistoriador' as Role,
            avatar: '',
          }))

        usersStore.syncUsers(validUsers)
        toast({
          title: 'Sincronização Entra ID Concluída',
          description: `${validUsers.length} usuários importados e validados do M365.`,
        })
      } catch (e: any) {
        toast({
          variant: 'destructive',
          title: 'Erro de Sincronização M365',
          description: e.message,
        })
      } finally {
        setIsSyncing(false)
      }
    } else {
      setTimeout(() => {
        const mockFetched = [
          {
            id: 'usr-1',
            name: 'Admin Sistema',
            email: `admin@${primaryDomain}`,
            role: 'Admin' as Role,
            avatar: '',
          },
          {
            id: 'usr-2',
            name: 'Ismail Abdo',
            email: `ismail@${primaryDomain}`,
            role: 'Diretor' as Role,
            avatar: '',
          },
          {
            id: 'usr-3',
            name: 'Mariana Costa',
            email: `mariana.costa@${primaryDomain}`,
            role: 'Jurídico' as Role,
            avatar: '',
          },
          {
            id: 'usr-4',
            name: 'Roberto Alves',
            email: `roberto.alves@${primaryDomain}`,
            role: 'Gerente' as Role,
            avatar: '',
          },
        ]
        usersStore.syncUsers(mockFetched)
        setIsSyncing(false)
        toast({
          title: 'Sincronização Simulada Concluída',
          description: `Usuários sincronizados para o domínio @${primaryDomain}. Cadastre credenciais reais na aba Integração para obter usuários online.`,
        })
      }, 1500)
    }
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Shield className="w-5 h-5 text-primary" /> Contas e Acessos M365
            </CardTitle>
            <CardDescription className="flex flex-col gap-1 mt-1">
              <span>
                Gerencie quais emails corporativos têm permissão para acessar a plataforma.
              </span>
              {primaryDomain ? (
                <span className="inline-flex items-center text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded w-fit mt-1">
                  <CheckCircle2 className="w-3 h-3 mr-1" /> Permissões restritas ao domínio
                  vinculado: @{primaryDomain}
                </span>
              ) : (
                <span className="inline-flex items-center text-xs font-medium text-destructive bg-destructive/10 border border-destructive/20 px-2 py-1 rounded w-fit mt-1">
                  <AlertCircle className="w-3 h-3 mr-1" /> Configure o Domínio Primário para
                  gerenciar acessos
                </span>
              )}
            </CardDescription>
          </div>
          <div className="flex gap-2 w-full sm:w-auto">
            <Button
              variant="outline"
              onClick={handleSyncM365}
              disabled={!primaryDomain || isSyncing}
              className="gap-2 flex-1 sm:flex-none"
            >
              {isSyncing ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <RefreshCw className="w-4 h-4" />
              )}
              Sincronizar M365
            </Button>
            <Button
              onClick={handleOpenNew}
              className="gap-2 flex-1 sm:flex-none"
              disabled={!primaryDomain}
            >
              <Plus className="w-4 h-4" /> Novo
            </Button>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Usuário</TableHead>
                <TableHead>Email M365 Autorizado</TableHead>
                <TableHead>Perfil de Acesso</TableHead>
                <TableHead className="text-right">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {users.map((user) => (
                <TableRow key={user.id}>
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <Avatar className="h-8 w-8">
                        <AvatarImage src={user.avatar} className="object-cover" />
                        <AvatarFallback>
                          <User className="h-4 w-4 text-muted-foreground" />
                        </AvatarFallback>
                      </Avatar>
                      <span className="font-medium">{user.name}</span>
                    </div>
                  </TableCell>
                  <TableCell className="text-muted-foreground">{user.email}</TableCell>
                  <TableCell>
                    <Select
                      value={user.role}
                      onValueChange={(val: Role) => handleRoleChange(user.id, val)}
                    >
                      <SelectTrigger className="w-[180px]">
                        <UserCog className="w-4 h-4 mr-2 text-muted-foreground" />
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {availableRoles.map((role) => (
                          <SelectItem key={role} value={role}>
                            {role}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </TableCell>
                  <TableCell className="text-right space-x-1">
                    <Button variant="ghost" size="icon" onClick={() => handleOpenEdit(user)}>
                      <Pencil className="w-4 h-4 text-muted-foreground" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => handleRemove(user.id)}
                      className="text-destructive hover:text-destructive hover:bg-destructive/10"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
              {users.length === 0 && (
                <TableRow>
                  <TableCell colSpan={4} className="text-center py-6 text-muted-foreground">
                    {primaryDomain
                      ? 'Nenhum usuário encontrado. Sincronize com o M365 ou adicione manualmente.'
                      : 'Cadastre o Domínio Primário na Integração SharePoint para gerenciar acessos.'}
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CloudUpload className="w-5 h-5 text-primary" /> Permissões de Integração SharePoint
          </CardTitle>
          <CardDescription>
            Defina quais perfis podem realizar uploads e sincronizar dados com o ambiente M365.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {availableRoles.map((role) => {
              const isChecked = settings.spIntegrationRoles?.includes(role) ?? false
              return (
                <div
                  key={role}
                  className="flex items-center space-x-2 border p-3 rounded-lg bg-card"
                >
                  <Checkbox
                    id={`sp-role-${role}`}
                    checked={isChecked}
                    onCheckedChange={(c) => toggleSpIntegrationRole(role, c as boolean)}
                  />
                  <Label
                    htmlFor={`sp-role-${role}`}
                    className="text-sm font-medium leading-none cursor-pointer"
                  >
                    {role}
                  </Label>
                </div>
              )
            })}
          </div>
        </CardContent>
      </Card>

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editId ? 'Editar Usuário M365' : 'Autorizar Novo Usuário'}</DialogTitle>
            <DialogDescription>
              Apenas contas pertencentes ao domínio oficial da organização podem ser cadastradas.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label>Nome Completo</Label>
              <Input
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="Ex: João Silva"
              />
            </div>
            <div className="grid gap-2">
              <Label>Identificação (Email)</Label>
              <div className="flex">
                <Input
                  className="rounded-r-none focus-visible:z-10"
                  value={localEmailPart}
                  onChange={(e) => setLocalEmailPart(e.target.value.replace(/@.*/, '').trim())}
                  placeholder="joao.silva"
                />
                <span className="inline-flex items-center px-3 border border-l-0 border-input rounded-r-md bg-muted text-muted-foreground text-sm font-medium">
                  @{primaryDomain}
                </span>
              </div>
            </div>
            <div className="grid gap-2">
              <Label>Perfil de Acesso Inicial</Label>
              <Select
                value={formData.role}
                onValueChange={(val: Role) => setFormData({ ...formData, role: val })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {availableRoles.map((role) => (
                    <SelectItem key={role} value={role}>
                      {role}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSave}>Salvar Usuário</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}
